function escapeHtml(text) {
  const replacements = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
  return String(text).replace(/[&<>"']/g, (character) => replacements[character]);
}

function renderInvoice({ invoice }) {
  const { number, billTo, from, email, details } = invoice;
  const address = (text) => String(text).split(/\r?\n/).map(escapeHtml).join("<br>");
  if (!Array.isArray(details) || details.length === 0)
    throw new Error("Add at least one invoice line item");
  let totalCents = 0;
  const money = (cents) => "$" + (cents / 100).toFixed(2);
  const rows = details
    .map(({ description, price, qty }) => {
      if (!Number.isFinite(price) || price < 0 || !Number.isSafeInteger(qty) || qty <= 0) {
        throw new Error(
          "Invoice line items need a nonnegative unit price and a positive whole quantity",
        );
      }
      const unitCents = Math.round(price * 100);
      const lineCents = unitCents * qty;
      totalCents += lineCents;
      if (!Number.isSafeInteger(totalCents))
        throw new Error("Invoice amount exceeds the supported range");
      return (
        "<tr><td>" +
        escapeHtml(description) +
        "</td><td>" +
        money(unitCents) +
        "</td><td>" +
        qty +
        "</td><td>" +
        money(lineCents) +
        "</td></tr>"
      );
    })
    .join("\n");
  const contact = escapeHtml(email);
  return {
    html: `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Invoice #${escapeHtml(number)}</title>
<style>
@page { size: Letter; margin: 15mm; }
* { box-sizing: border-box; }
body { margin: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; color: #152644; font: 13px/1.45 Arial, sans-serif; }
header { background: #164b8f; color: white; padding: 23px 25px; border-radius: 9px; }
h1 { font-size: 34px; line-height: 1.1; margin: 0 0 5px; }
header p { margin: 0; }
.parties { display: table; table-layout: fixed; width: 100%; margin: 24px 0; }
.parties section { display: table-cell; width: 50%; }
h2 { color: #164b8f; font-size: 14px; margin: 0 0 4px; }
table { width: 100%; border-collapse: collapse; }
thead, tfoot { background: #eaf1fa; }
th, td { padding: 11px 9px; border-bottom: 1px solid #e5ebf3; }
th:first-child, td:first-child { text-align: left; }
th:not(:first-child), td:not(:first-child) { text-align: right; white-space: nowrap; }
thead { display: table-header-group; }
tr { break-inside: avoid; }
footer { margin-top: 25px; color: #4a596d; }
footer p { margin: 5px 0; }
a { color: #164b8f; }
</style>
</head>
<body>
<header><h1>Invoice</h1><p>Invoice #${escapeHtml(number)}</p></header>
<div class="parties"><section><h2>Billed to</h2>${address(billTo)}</section>
<section><h2>From</h2>${address(from)}<br>Email: ${contact}</section></div>
<table>
<thead><tr><th>Description</th><th>Unit price</th><th>Quantity</th><th>Total</th></tr></thead>
<tbody>${rows}</tbody>
<tfoot><tr><th colspan="3">Total amount</th><td><strong>${money(totalCents)}</strong></td></tr></tfoot>
</table>
<footer><p>Thank you for doing business with us.</p><p><a href="mailto:${contact}">Contact us</a></p></footer>
</body>
</html>`,
  };
}

const invoice = {
  number: "1",
  billTo: "Example Customer\nExample City, 00000",
  from: "Example Studio\nExample City, 00001",
  email: "billing@example.com",
  details: [
    {
      description: "Web Hosting",
      price: 150,
      qty: 2,
    },
    {
      description: "Domain",
      price: 15,
      qty: 5,
    },
  ],
};
return { json: renderInvoice({ invoice }) };
